const input=$input.first().json;
try {
  const base=$env.INSULA_CRM_BASE_URL, apiKey=$env.INSULA_CRM_API_KEY;
  const leadId=Number(input.insulaLeadId||input.leadId||input.lead_id||input.property_identity?.lead_id||input.identity?.lead_id||input.transaction_ids?.lead_id||input.crm_update?.lead_id||0);
  if(base&&apiKey&&leadId){
    const payload=input.buyer_selection_exit_strategy||input.buyer_matching||input.buyer_disposition||input.exit_strategy_gate||input;
    await this.helpers.httpRequest({
      method:'POST',url:base+'/api/v1/activities',
      headers:{'X-API-Key':apiKey,'Content-Type':'application/json',
        'Idempotency-Key':'acquisition:buyer-selection-exit-strategy:'+leadId+':'+String(input.candidate_key||input.normalized_identity_key||input.external_id||input.dealId||input.deal_id||'record')+':v1'},
      body:{lead_id:leadId,type:'stage_change',
        subject:"Buyer selection / exit strategy evaluated",
        body:'Workflow event: buyer-selection-exit-strategy. Status/readiness: '+String(payload.status||payload.readiness||payload.current_status||payload.closeout_status||payload.post_close_status||payload.transaction_status||'updated')+'. Next action: '+String(payload.next_action||input.next_action||'review').slice(0,500)},
      json:true
    });
  }
}catch(error){ console.log('InsulaCRM activity sync failed:',error.message); }
return [{json:input}];
